// Pings older than this are treated as offline/stale on maps
var GPS_STALE_MS = 90 * 1000;
var lastMovedLat = null;
var lastMovedLng = null;
var lastMovedTime = Date.now();
var stallAlertSent = false;

function checkGPSStall(lat,lng,driverId,driverName,jobId){
  var moved = !lastMovedLat || Math.abs(lat-lastMovedLat)>0.0001 || Math.abs(lng-lastMovedLng)>0.0001;
  if(moved){ lastMovedLat=lat; lastMovedLng=lng; lastMovedTime=Date.now(); stallAlertSent=false; return; }
  var stallMs=(Date.now()-lastMovedTime);
  var cfg=loadSafetyConfig();
  var stallLimit=(cfg.stallMinutes||GPS_STALL_MINUTES)*60000;
  if(stallMs>stallLimit&&!stallAlertSent&&jobId){
    stallAlertSent=true;
    sendEmergencyAlert(driverId,driverName,lat,lng,jobId,"GPS STALL — truck has not moved for "+(Math.round(stallMs/60000))+" minutes during active job");
  }
}
