function getOfflineQueue(){ try{ return JSON.parse(localStorage.getItem(OFFLINE_QUEUE_KEY)||"[]"); }catch(e){ return []; } }
function saveOfflineQueue(q){ try{ localStorage.setItem(OFFLINE_QUEUE_KEY,JSON.stringify(q)); }catch(e){} }
function addToOfflineQueue(job){
  var q=getOfflineQueue();
  if(q.find(function(j){return j.id===job.id;})) return;
  q.push(Object.assign({},job,{_offlineId:"OFF-"+Date.now(),_offlinePending:true}));
  saveOfflineQueue(q);
}
function removeFromOfflineQueue(jobId){
  saveOfflineQueue(getOfflineQueue().filter(function(j){return j.id!==jobId;}));
}
if(typeof window!=="undefined"&&"serviceWorker" in navigator){
  window.addEventListener("load",function(){
    navigator.serviceWorker.register("/sw.js")
      .then(function(){ /* SW registered */ })
      .catch(function(e){ /* SW registration failed */ });
  });
}

