  var payload={user_id:userId,cdl_number:data.cdlNumber||null,cdl_expiry:data.cdlExpiry||null,med_card_expiry:data.medCardExpiry||null,mvr_date:data.mvrDate||null,drug_test_date:data.drugTestDate||null,alcohol_test_date:data.alcoholTestDate||null,clearinghouse:data.clearinghouse||null,dot_insp_date:data.dotInspDate||null,dot_insp_result:data.dotInspResult||null,accident_count:data.accidentCount||0,ticket_count:data.ticketCount||0,accident_notes:data.accidentNotes||null,updated_at:new Date().toISOString()};
