    var jobsWithSla = completed.filter(function (j) { return j.slaPickupWindowMin && j.scheduledTime && j.arrivedAt; });
    var metCount = jobsWithSla.filter(function (j) { var s = slaStatus(j); return s && s.indexOf("Met") > -1; }).length;
