            fetch(SUPABASE_URL + "/rest/v1/junk_jobs?id=eq." + job.id, { method: "PATCH", headers: sbHeaders(), body: JSON.stringify({ ai_detected_items: merged, ai_addon_price: addonTotal }) }).catch(function () {});
